import { tags } from "typia";

/**
 * Aggregated security metrics for a single actor type (customers, sellers, or
 * platform administrators).
 *
 * Each segment summarizes identity counts, session activity, and security event
 * tallies for the corresponding actor group. These metrics are derived from the
 * relevant identity table, session table, and security/auth log tables, and are
 * optimized for admin dashboard visualizations.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallActorSecurityOverviewActorSegment = {
  /**
   * Total number of actor identities of this type currently registered in the
   * platform (for example, total customers or total sellers).
   *
   * This count is typically derived from the corresponding identity table
   * such as shopping_mall_customer, shopping_mall_seller, or
   * shopping_mall_platformadmin.
   */
  totalActors: number & tags.Type<"int32">;

  /**
   * Current number of active sessions for this actor type.
   *
   * This value is usually computed from the corresponding session table (for
   * example, shopping_mall_customer_sessions) by counting sessions that are
   * not yet expired or closed.
   */
  activeSessions: number & tags.Type<"int32">;

  /**
   * Number of sessions for this actor type that have been created within the
   * recent aggregation window defined by the overview (for example, the last
   * 60 minutes).
   *
   * This helps administrators understand short-term authentication activity
   * trends.
   */
  recentSessions: number & tags.Type<"int32">;

  /**
   * Total number of failed login attempts for this actor type within the
   * recent aggregation window.
   *
   * This is typically computed by counting failed authentication events in
   * shopping_mall_security_events or shopping_mall_auth_logs.
   */
  failedLoginAttempts: number & tags.Type<"int32">;

  /**
   * Total number of successful logins for this actor type within the recent
   * aggregation window.
   *
   * This metric complements failedLoginAttempts to give a fuller picture of
   * authentication outcomes.
   */
  successfulLogins: number & tags.Type<"int32">;

  /**
   * Number of actor identities of this type that are currently locked due to
   * security policies such as too many failed login attempts or risk flags.
   *
   * This is typically derived from flags or status fields in identity or
   * credential tables.
   */
  lockedAccounts: number & tags.Type<"int32">;

  /**
   * Number of multi-factor authentication (MFA) challenges that have been
   * triggered for this actor type within the recent aggregation window.
   *
   * This metric helps assess the frequency of elevated authentication flows
   * for the actor group.
   */
  mfaChallenges: number & tags.Type<"int32">;
};
